  b=float(method[3:]); key=lambda a:len(by[a])+b*sum(s['score'] for s in by[a])
 elif method.startswith('exp'):
  b=float(method[3:]); key=lambda a:sum(math.exp(b*s['score']) for s in by[a])
 elif method.startswith('thr'):
  t=float(method[3:]); key=lambda a:sum(s['score']>t for s in by[a])
 elif method.startswith('wins'):
  t=float(method[4:]); key=lambda a:sum(max(0,s['score']-t) for s in by[a])
 else: raise ValueError(method)
 # stable tie by first occurrence
 vals={a:key(a) for a in by}; m=max(vals.values())
 return next(s['answer'] for s in ss if vals[s['answer']]==m)

def eval_alloc(alloc,method,topic=None,N=100):
 qs=[q for q in recs if topic is None or q['topic']==topic]
 good=0; total=0
 for _ in range(N):
  for q in qs:
   ss=[]
   for v,k in enumerate(alloc):
    pool=[s for s in q['samples'] if s['variant']==v]
    for i in range(k): ss.append(random.choice(pool))
   good += pick(ss,method)==q['correct_answer']; total+=1
 return good/total
allocs=[]
# all compositions of 6 into 5, plus selected variants
for a in itertools.product(range(7),repeat=5):
 if sum(a)==6: allocs.append(a)
methods=['maj','sum','mean']+['lin%.2f'%x for x in [-2,-1,-.5,-.2,-.1,.1,.2,.5,1,2]]+['exp%.1f'%x for x in [.2,.5,1,2]]+['thr%.1f'%x for x in [-.5,0,.3,.5,.8,1,1.2,1.5]]+['wins%.1f'%x for x in [-.5,0,.3,.5,.8,1,1.2]]
for topic in ['algebra','geometry','combinatorics','number_theory',None]:
 best=[]
 for alloc in allocs:
  for method in methods:
   val=eval_alloc(alloc,method,topic,N=12 if topic is None else 20)
   best.append((val,alloc,method))
 print('\n',topic)
 for x in sorted(best,reverse=True)[:20]: print('%.4f'%x[0],x[1],x[2])
